import { UserPlus, Mail, Link2, CheckCircle } from "lucide-react";

const steps = [
  {
    icon: UserPlus,
    step: "01",
    title: "Enter Your Email",
    description:
      "User visits the login page and enters their email address. No password field needed.",
    color: "from-primary/20 to-accent/20",
  },
  {
    icon: Link2,
    step: "02",
    title: "Magic Link Generated",
    description:
      "The system generates a unique, secure token and creates a one-time-use magic link.",
    color: "from-accent/20 to-primary/20",
  },
  {
    icon: Mail,
    step: "03",
    title: "Email Delivered",
    description:
      "The magic link is sent to the user's email inbox. The link expires after a set time.",
    color: "from-primary/20 to-accent/20",
  },
  {
    icon: CheckCircle,
    step: "04",
    title: "Click & Logged In",
    description:
      "User clicks the link, the token is verified, and they're instantly authenticated.",
    color: "from-accent/20 to-primary/20",
  },
];

const HowItWorksSection = () => {
  return (
   <section id="about" className="section py-24">

<div className="container-ui grid md:grid-cols-4 gap-6">

{features.map((f)=>(

<div
key={f.title}
className="glass card-hover p-6"
>

<f.icon className="text-cyan-400 mb-4"/>

<h3 className="font-bold mb-2">

{f.title}

</h3>

<p className="text-sm opacity-80">

{f.description}

</p>

</div>

))}

</div>

</section>
  );
};

export default HowItWorksSection;
